#!/usr/bin/env node
// Generated by Keel — read-only drift check: docs against the repo. Copy to .keel/check.mjs (every upgrade).
// Usage: node .keel/check.mjs [--json]     report findings; writes nothing, ever
//        node .keel/check.mjs --self-test
// Exit 0 = clean, 1 = findings. One finding per line: [kind] file:line message.
// Kinds:
//   missing-file     a file every keel project has: AGENTS.md, CLAUDE.md, .keel/meta.json, .keel/doc-size.mjs
//   dead-link        a relative Markdown link whose file, or #heading in a .md file, does not exist
//   adr-missing      an unlinked ADR index row (not Reserved) with no docs/adr/ADR-NNN-*.md file (a linked one is a dead-link)
//   adr-unindexed    an ADR file with no row in docs/adr/README.md
//   adr-status       index Status stage ≠ the file's latest Status stage, or "Superseded by" an ADR that does not exist
//   phase-gates-open a ✅ phase whose exit-gate table still has a ⬜ or 🔄 row
//   phase-path       a path cited by a ✅ phase (Evidence, ✅ gate artefact, [x] deliverable) or a non-✅
//                    phase's Workflow script that does not exist
//   stack-undocumented  a runtime dependency (package.json dependencies, requirements.txt, go.mod, Cargo.toml)
//                    named in no record doc (ARCHITECTURE, HLD, LLD, ENGINEERING_DESIGN, NFR, ADRs, AGENTS.md)
// Scanned: AGENTS.md, CLAUDE.md, root CHANGELOG/COMMANDS/RUNBOOK.md, docs/**.md. Archives (ARCHIVE in the
// name, LEGACY_*, archive/ folders) are history: never scanned, only link targets. Fenced code, inline code
// and HTML comments are skipped, as is anything holding {{.
import { readdirSync, readFileSync, existsSync, statSync, writeFileSync, mkdirSync, mkdtempSync } from 'fs'
import { join, posix } from 'path'
import { tmpdir } from 'os'

const { dirname, basename, normalize } = posix
const ROOT_DOCS = ['AGENTS.md', 'CLAUDE.md', 'CHANGELOG.md', 'COMMANDS.md', 'RUNBOOK.md']
const REQUIRED = ['AGENTS.md', 'CLAUDE.md', '.keel/meta.json', '.keel/doc-size.mjs']
const RECORD = /(^|\/)(ARCHITECTURE|HLD|LLD|ENGINEERING_DESIGN|NFR)\.md$|(^|\/)adr\/|^AGENTS\.md$|^docs\/(architecture|hld|lld|engineering-design|nfr)\//i
const isArchive = f => /ARCHIVE/i.test(basename(f)) || /^LEGACY_/i.test(basename(f)) || /(^|\/)archive\//i.test(f)
const ADR_FILE = /^docs\/adr\/(ADR-(\d+))[^/]*\.md$/i
const STAGES = ['reserved', 'proposed', 'accepted', 'built', 'superseded']
// A Status cell is "Proposed … · Accepted … · Built `abc` …": its stage is the last " · " segment that
// starts with a stage word (so "Accepted (implemented). Built via …" stays accepted).
const stage = s => s.split(/\s·\s/).reduce((best, seg) => {
  const i = STAGES.findIndex(st => new RegExp(`^\\W*${st}\\b`, 'i').test(seg.trim()))
  return i >= 0 ? i : best
}, -1)

// Blank out code fences, inline code and HTML comments, keeping line numbers.
const blank = s => s.replace(/[^\n]/g, ' ')
const prose = t => t.replace(/```[\s\S]*?```|~~~[\s\S]*?~~~|<!--[\s\S]*?-->/g, blank).replace(/`[^`\n]*`/g, blank)
const lineOf = (text, i) => text.slice(0, i).split('\n').length
export const slug = h => h.trim().toLowerCase().replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/`/g, '')
  .replace(/[^\p{L}\p{N}\s_-]/gu, '').replace(/ /g, '-')
function anchors(text) {
  const out = new Set(), seen = {}
  for (const [, h] of text.replace(/```[\s\S]*?```|~~~[\s\S]*?~~~|<!--[\s\S]*?-->/g, blank).matchAll(/^#{1,6}\s+(.+?)\s*#*\s*$/gm)) {
    const s = slug(h), n = seen[s] = (seen[s] ?? -1) + 1
    out.add(n ? `${s}-${n}` : s)
  }
  for (const [, id] of text.matchAll(/\b(?:id|name)="([^"]+)"/g)) out.add(id)
  return out
}

function walk(root, dir, acc = []) {
  if (!existsSync(join(root, dir))) return acc
  for (const e of readdirSync(join(root, dir), { withFileTypes: true })) {
    const p = dir ? `${dir}/${e.name}` : e.name
    if (e.isDirectory() && e.name !== 'node_modules' && !e.name.startsWith('.')) walk(root, p, acc)
    else if (e.isFile() && e.name.endsWith('.md')) acc.push(p)
  }
  return acc
}

export function check(root) {
  const findings = [], add = (kind, file, line, msg) => findings.push({ kind, file, line, msg })
  const read = f => readFileSync(join(root, f), 'utf8')
  const exists = f => existsSync(join(root, f))
  const docs = [...ROOT_DOCS.filter(exists), ...walk(root, 'docs')].filter(f => !isArchive(f))
  const texts = new Map(docs.map(f => [f, read(f)]))
  const anchorCache = new Map()
  const anchorsOf = f => anchorCache.get(f) ?? anchorCache.set(f, anchors(read(f))).get(f)
  let links = 0

  for (const f of REQUIRED) if (!exists(f)) add('missing-file', f, 0, 'expected in every keel project')

  // Dead links.
  for (const [f, text] of texts) {
    for (const m of prose(text).matchAll(/\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g)) {
      const target = m[1]
      if (/^[a-z][\w+.-]*:/i.test(target) || target.includes('{{')) continue
      links++
      const [path, hash] = target.split('#')
      const file = !path ? f : normalize(path.startsWith('/') ? path.slice(1) : join(dirname(f), decodeURIComponent(path)))
      const line = lineOf(text, m.index)
      if (file.startsWith('..') || !exists(file)) { add('dead-link', f, line, `${target}: no such file${ADR_FILE.test(f) ? ' (the ADR is immutable: restore the target or leave a redirect stub)' : ''}`); continue }
      if (hash && file.endsWith('.md') && !statSync(join(root, file)).isDirectory() && !anchorsOf(file).has(decodeURIComponent(hash).toLowerCase()) && !anchorsOf(file).has(hash))
        add('dead-link', f, line, `${target}: no heading #${hash} in ${file}${ADR_FILE.test(f) ? ' (the ADR is immutable: restore the heading or an anchor in the target)' : ''}`)
    }
  }

  // ADRs: index vs files.
  const adrFiles = new Map() // ADR-NNN → file
  for (const f of docs) { const m = f.match(ADR_FILE); if (m) adrFiles.set(m[1].toUpperCase().replace(/-0*(\d)/, (_, d) => `-${d}`), f) }
  const norm = id => id.toUpperCase().replace(/-0*(\d)/, (_, d) => `-${d}`)
  const index = 'docs/adr/README.md', indexed = new Set()
  if (texts.has(index)) {
    const text = texts.get(index)
    const rows = [...prose(text).matchAll(/^\|[^\n]*$/gm)]
    for (const r of rows) {
      const cells = text.slice(r.index, r.index + r[0].length).split('|').slice(1, -1).map(c => c.trim())
      const id = cells[0]?.match(/ADR-\d+/i)?.[0]
      if (!id || cells.length < 3 || /^OD-/.test(cells[0])) continue
      const key = norm(id), line = lineOf(text, r.index), status = cells[2]
      indexed.add(key)
      const file = adrFiles.get(key)
      if (!file) { if (!/reserved/i.test(cells.join(' ')) && !cells[0].includes('](')) add('adr-missing', index, line, `${id} is indexed but has no file in docs/adr/`); continue }
      const fileStatus = read(file).match(/^\|\s*\*\*Status\*\*\s*\|([^\n]*)\|/m)?.[1] ?? ''
      const a = stage(status), b = stage(fileStatus)
      if (a >= 0 && b >= 0 && a !== b) add('adr-status', index, line, `${id}: index says ${STAGES[a]}, ${file} says ${STAGES[b]}`)
    }
    for (const [key, file] of adrFiles) if (!indexed.has(key)) add('adr-unindexed', file, 1, `no row in ${index}`)
  }
  for (const [f, text] of texts) {
    if (!f.startsWith('docs/adr/')) continue
    for (const m of prose(text).matchAll(/superseded by\s+\[?(ADR-\d+)/gi))
      if (!adrFiles.has(norm(m[1])) && !indexed.has(norm(m[1]))) add('adr-status', f, lineOf(text, m.index), `superseded by ${m[1]}, which does not exist`)
  }

  // Plan: phase status vs phase blocks and the paths they cite.
  const planFiles = docs.filter(f => f === 'docs/IMPLEMENTATION_PLAN.md' || f.startsWith('docs/implementation-plan/'))
  const status = new Map(), blocks = []
  for (const f of planFiles) {
    const text = texts.get(f), p = prose(text)
    for (const r of p.matchAll(/^\|\s*([\d.]+)\s*(?:—|-|–)[^|]*\|\s*(✅|🔄|⬜)/gm)) status.set(r[1], r[2])
    const heads = [...p.matchAll(/^## Phase ([\d.]+)\b.*$/gm)]
    heads.forEach((h, i) => {
      const end = i + 1 < heads.length ? heads[i + 1].index : (p.slice(h.index + 1).search(/^## /m) + h.index + 1 || text.length)
      blocks.push({ n: h[1], file: f, start: h.index, text: text.slice(h.index, end > h.index ? end : text.length) })
    })
  }
  const pathTokens = s => [...s.matchAll(/`([^`\s]+)`/g)].map(m => ({ i: m.index, p: m[1].replace(/:\d+(:\d+)?$/, '') }))
    .filter(({ p }) => p.includes('/') && !/[{*<>]|^https?:|^-/.test(p) && !/\s/.test(p))
  for (const b of blocks) {
    const st = status.get(b.n)
    if (!st || /PHASE_ARCHIVE/i.test(b.text)) continue
    const at = i => lineOf(texts.get(b.file), b.start + i)
    const missing = (p, i, why) => { if (!exists(p.replace(/^\.\//, '').replace(/\/$/, ''))) add('phase-path', b.file, at(i), `Phase ${b.n} (${st}) ${why} \`${p}\` does not exist`) }
    if (st !== '✅') {
      const w = b.text.match(/\*\*Workflow:\*\*\s*`([^`]+)`/)
      if (w && !w[1].includes('{{')) missing(w[1], w.index, 'workflow')
      continue
    }
    const gateRows = [...b.text.matchAll(/^\|(?!\s*-)(?!\s*Gate\s*\|)[^\n]*\|\s*(✅|⬜|🔄|❌)[^|\n]*\|\s*$/gm)]
    const open = gateRows.filter(r => r[1] !== '✅')
    if (open.length) add('phase-gates-open', b.file, at(open[0].index), `Phase ${b.n} is ✅ but ${open.length} exit gate(s) are not`)
    for (const r of gateRows.filter(r => r[1] === '✅')) for (const t of pathTokens(r[0])) missing(t.p, r.index + t.i, 'gate artefact')
    for (const d of b.text.matchAll(/^\s*- \[x\][^\n]*$/gim)) for (const t of pathTokens(d[0])) missing(t.p, d.index + t.i, 'deliverable')
    const e = b.text.match(/\*\*Evidence:\*\*\s*`([^`]+)`/)
    if (e && !e[1].includes('{{')) missing(e[1], e.index, 'evidence')
  }

  // Stack: runtime dependencies no record doc names.
  const deps = []
  if (exists('package.json')) { try { deps.push(...Object.keys(JSON.parse(read('package.json')).dependencies || {}).map(d => ['package.json', d])) } catch { add('stack-undocumented', 'package.json', 0, 'not valid JSON; dependencies not checked') } }
  if (exists('requirements.txt')) for (const l of read('requirements.txt').split('\n')) { const m = l.match(/^\s*([A-Za-z0-9][\w.-]*)/); if (m) deps.push(['requirements.txt', m[1]]) }
  if (exists('go.mod')) for (const m of read('go.mod').matchAll(/^\s*(?:require\s+)?([\w.-]+\.[a-z]+\/[^\s]+)\s+v[\d.]+(?!.*\/\/ indirect)/gm)) deps.push(['go.mod', m[1]])
  if (exists('Cargo.toml')) { const sec = read('Cargo.toml').match(/^\[dependencies\]\n([\s\S]*?)(?=^\[|$(?![\s\S]))/m); if (sec) for (const m of sec[1].matchAll(/^([\w-]+)\s*=/gm)) deps.push(['Cargo.toml', m[1]]) }
  const corpus = docs.filter(f => RECORD.test(f)).map(f => texts.get(f)).join('\n').toLowerCase()
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  for (const [manifest, d] of deps) {
    if (d.startsWith('@types/')) continue
    const names = new Set([d, d.replace(/^@[^/]+\//, ''), d.split('/').pop(), d.replace(/^@/, '').split('/')[0]].map(n => n.toLowerCase()).filter(n => n.length > 1))
    if (![...names].some(n => new RegExp(`(^|[^\\w-])${esc(n)}($|[^\\w-])`).test(corpus)))
      add('stack-undocumented', manifest, 0, `dependency "${d}" is named in no record doc (ARCHITECTURE, HLD, LLD, ENGINEERING_DESIGN, NFR, ADRs, AGENTS.md)`)
  }

  return { findings, scanned: { docs: docs.length, links, adrs: adrFiles.size, phases: status.size, deps: deps.length } }
}

export function report({ findings, scanned }) {
  const head = `keel check: ${findings.length ? `${findings.length} finding(s)` : 'clean'} — ${scanned.docs} docs, ${scanned.links} links, ${scanned.adrs} ADRs, ${scanned.phases} phases, ${scanned.deps} dependencies checked (read-only; nothing written)`
  return [head, ...findings.map(f => `[${f.kind}] ${f.file}${f.line ? `:${f.line}` : ''} ${f.msg}`)].join('\n')
}

if (process.argv.includes('--self-test')) {
  const assert = (c, m) => { if (!c) { console.error(`self-test FAIL: ${m}`); process.exit(1) } }
  const mk = files => {
    const d = mkdtempSync(join(tmpdir(), 'keel-check-'))
    for (const [f, t] of Object.entries(files)) { mkdirSync(join(d, dirname(f)), { recursive: true }); writeFileSync(join(d, f), t) }
    return d
  }
  const plan = (st, gate, extra = '') => `# Plan\n\n### Phase status\n\n| Phase | Status |\n|---|---|\n| 0 — Guardrails | ${st} |\n| 1 — Core | ⬜ |\n\n## Phase 0 — Guardrails\n\n- [x] tests: \`tests/rules.test.js\`\n\n| Gate | Evidence level | Artefact | Verified by | Status |\n|---|---|---|---|---|\n| Rule suite green | \`unit\` | \`tests/rules.test.js\` | agent | ${gate} |\n\n**Workflow:** \`.claude/workflows/phase-0-guardrails.js\` · **Evidence:** \`.keel/evidence/phase-0.json\`\n${extra}\n## Phase 1 — Core\n\n**Workflow:** \`.claude/workflows/phase-1-core.js\`\n`
  const adr = st => `# ADR-001 — Store — Postgres\n\n| | |\n|---|---|\n| **Status** | ${st} |\n`
  const clean = {
    'AGENTS.md': '# App\n\nSee [the plan](docs/IMPLEMENTATION_PLAN.md#phase-0--guardrails) and [HLD](docs/HLD.md#data--pg-only). Uses express.\n',
    'CLAUDE.md': '@AGENTS.md\n', '.keel/meta.json': '{}', '.keel/doc-size.mjs': '',
    'package.json': JSON.stringify({ dependencies: { express: '4', '@prisma/client': '5' }, devDependencies: { vitest: '1' } }),
    'docs/HLD.md': '# HLD\n\n## Data — `pg` only\n\nPrisma over Postgres ([ADR-001](adr/ADR-001-store.md)). `[x](missing.md)` in code is ignored.\n\n<!-- [y](gone.md) -->\n',
    'docs/IMPLEMENTATION_PLAN.md': plan('✅', '✅'),
    'docs/adr/README.md': '# ADRs\n\n| ADR | Title | Status | Deciders | Date |\n|---|---|---|---|---|\n| [ADR-001](./ADR-001-store.md) | Store — Postgres | Built | eng | 2026-01-01 |\n| [ADR-006](./ADR-006-log.md) | Log — pino | Accepted | eng | 2026-01-06 |\n| ADR-002 | Reserved (Phase 1) — cache | Proposed | — | — |\n',
    'docs/adr/ADR-001-store.md': adr('Proposed 2026-01-01 · Accepted 2026-01-02 · Built `abc` 2026-01-09'),
    'docs/adr/ADR-006-log.md': adr('Accepted (implemented). Merged; built via 3 agents · —'),
    'docs/PHASE_ARCHIVE.md': '[dead](nowhere.md)\n',
    'tests/rules.test.js': '', '.claude/workflows/phase-0-guardrails.js': '', '.claude/workflows/phase-1-core.js': '',
    '.keel/evidence/phase-0.json': '{}',
  }
  const ok = check(mk(clean))
  assert(ok.findings.length === 0, `clean fixture has findings:\n${report(ok)}`)
  assert(ok.scanned.links === 5 && ok.scanned.adrs === 2 && ok.scanned.phases === 2 && ok.scanned.deps === 2, `scanned counts ${JSON.stringify(ok.scanned)}`)

  // Break each thing once; each must be reported with the right kind (a check proven to fail).
  const broken = { ...clean,
    '.keel/doc-size.mjs': undefined,
    'AGENTS.md': clean['AGENTS.md'] + 'Also [gone](docs/GONE.md) and [bad anchor](docs/HLD.md#nope).\n',
    'package.json': JSON.stringify({ dependencies: { express: '4', '@prisma/client': '5', zod: '3' } }),
    'docs/IMPLEMENTATION_PLAN.md': plan('✅', '⬜'),
    'docs/adr/README.md': clean['docs/adr/README.md'] + '| [ADR-003](./ADR-003-queue.md) | Queue — SQS | Accepted | eng | 2026-01-03 |\n| ADR-005 | Auth — OIDC | Accepted | eng | 2026-01-05 |\n',
    'docs/adr/ADR-001-store.md': adr('Proposed 2026-01-01 · Accepted 2026-01-02 · ⚠️ Superseded by ADR-009 2026-02-01'),
    'docs/adr/ADR-004-orphan.md': adr('Accepted 2026-01-04'),
    'tests/rules.test.js': undefined, '.claude/workflows/phase-1-core.js': undefined, '.keel/evidence/phase-0.json': undefined,
  }
  const res = check(mk(Object.fromEntries(Object.entries(broken).filter(([, v]) => v !== undefined))))
  const has = (kind, re) => res.findings.some(f => f.kind === kind && re.test(`${f.file}:${f.line} ${f.msg}`))
  const want = [
    ['missing-file', /\.keel\/doc-size\.mjs/],
    ['dead-link', /AGENTS\.md:4 docs\/GONE\.md: no such file/],
    ['dead-link', /docs\/HLD\.md#nope: no heading/],
    ['dead-link', /\.\/ADR-003-queue\.md: no such file/],
    ['adr-missing', /ADR-005 is indexed/],
    ['adr-unindexed', /ADR-004-orphan\.md/],
    ['adr-status', /ADR-001: index says built, .* says superseded/],
    ['adr-status', /superseded by ADR-009/],
    ['phase-gates-open', /Phase 0 is ✅ but 1 exit gate/],
    ['phase-path', /deliverable `tests\/rules\.test\.js`/],
    ['phase-path', /evidence `\.keel\/evidence\/phase-0\.json`/],
    ['phase-path', /Phase 1 \(⬜\) workflow/],
    ['stack-undocumented', /"zod"/],
  ]
  for (const [k, re] of want) assert(has(k, re), `expected [${k}] ${re}\n${report(res)}`)
  assert(res.findings.length === want.length, `expected ${want.length} findings, got ${res.findings.length}\n${report(res)}`)
  assert(!res.findings.some(f => /PHASE_ARCHIVE|missing\.md|gone\.md/.test(`${f.file} ${f.msg}`)), 'archives, code and comments must be skipped')
  console.log(`keel check self-test: ok (clean fixture clean; ${want.length} planted drifts each reported once)`)
  process.exit(0)
}

const res = check('.')
console.log(process.argv.includes('--json') ? JSON.stringify(res, null, 1) : report(res))
process.exit(res.findings.length ? 1 : 0)
